#[wasm_bindgen(js_name = Label)]
pub fn js_label(
    value: JsBindingTextArg,
    semantic_name: Option<String>,
    color: Option<ClassArg<JsColor>>,
    font_size: Option<f64>,
    line_height: Option<f64>,
    weight: Option<u32>,
    single_line: Option<bool>,
    selectable: Option<bool>,
) -> Result<JsWidget> {
    let color = color.map(|value| value.value()).transpose()?;
    let options = BindingLabelOptions {
        color: color.map(Into::into),
        font_size: font_size.map(|value| value as f32),
        line_height: line_height.map(|value| value as f32),
        weight: weight.map(|value| FontWeight::new(value.min(u32::from(u16::MAX)) as u16)),
        single_line: single_line.unwrap_or(false),
        selectable: selectable.unwrap_or(false),
    };
    JsWidget::from_binding(BindingWidget::label_with_options(
        binding_text_from_js(value)?,
        options,
    ))
    .with_semantic_name(semantic_name)
}

#[wasm_bindgen(js_name = Button)]
pub fn js_button(
    label: JsBindingTextArg,
    on_press: Option<Function>,
    enabled: Option<JsBindingBoolArg>,
    appearance: Option<String>,
    tone: Option<String>,
    icon: Option<String>,
    min_width: Option<f64>,
    semantic_name: Option<String>,
    description: Option<String>,
) -> Result<JsWidget> {
    let appearance = appearance
        .map(|value| {
            binding_button_appearance_from_name(&value)
                .ok_or_else(|| invalid_arg(format!("unknown button appearance '{value}'")))
        })
        .transpose()?;
    let options = BindingButtonOptions {
        appearance,
        tone: tone.as_deref().map(semantic_tone_from_js).transpose()?,
        icon: icon.as_deref().map(icon_glyph_from_js).transpose()?,
        min_width: min_width.map(|value| value as f32),
        description,
    };
    JsWidget::from_binding(BindingWidget::button_with_options(
        binding_text_from_js(label)?,
        js_action(on_press),
        options,
    ))
    .with_enabled(enabled)?
    .with_semantic_name(semantic_name)
}

