/// Map the class instances of `items` with `map`; `undefined` and `null`
/// items fail with `missing(index)`.
pub(crate) fn extract_indexed_classes<T: JsClass, R>(
    items: &Array,
    missing: impl Fn(u32) -> String,
    map: impl Fn(&T) -> R,
) -> Result<Vec<R>> {
    let mut out = Vec::with_capacity(items.length() as usize);
    for (index, item) in (0..).zip(items.iter()) {
        if item.is_undefined() || item.is_null() {
            return Err(invalid_arg(missing(index)));
        }
        out.push(map(&*class_ref::<T>(&item)?));
    }
    Ok(out)
}

