pub(crate) fn js_flex(
    axis: Axis,
    children: Array,
    gap: Option<f64>,
    justify: Option<String>,
    align_items: Option<String>,
    wrap: Option<bool>,
) -> Result<JsWidget> {
    let justify = justify
        .map(|value| {
            binding_flex_justify_from_name(&value)
                .ok_or_else(|| invalid_arg(format!("unknown justify '{value}'")))
        })
        .transpose()?;
    Ok(JsWidget::from_binding(BindingWidget::flex_with_options(
        axis,
        extract_binding_widgets(&children)?,
        gap.unwrap_or(0.0) as f32,
        BindingFlexOptions {
            justify,
            align_items: align_items.as_deref().map(alignment_from_js).transpose()?,
            wrap: wrap.unwrap_or(false),
        },
    )))
}

