#[wasm_bindgen(js_name = RebuildOnChange)]
pub fn js_rebuild_on_change(states: Array, build: Function) -> Result<JsWidget> {
    let states = states
        .iter()
        .map(|state| Ok(class_ref::<JsState>(&state)?.inner.clone()))
        .collect::<Result<Vec<_>>>()?;
    let build = Local(build);
    let builder = BindingWidgetBuilder::new(move || {
        let value = call_js(&build, &[])?;
        class_ref::<JsWidget>(&value)
            .and_then(|widget| widget.binding_widget())
            .map_err(callback_failure)
    });
    Ok(JsWidget::from_binding(BindingWidget::rebuild_on_change(
        states, builder,
    )))
}

