#[wasm_bindgen(js_name = Grid)]
pub fn js_grid(
    children: Array,
    columns: Option<JsValue>,
    name: Option<String>,
    gap: Option<f64>,
    column_gap: Option<f64>,
    row_gap: Option<f64>,
    rows: Option<Array>,
) -> Result<JsWidget> {
    let gap = gap.unwrap_or(0.0) as f32;
    // A count means that many equal columns; an array gives each track.
    let columns = match columns {
        None => vec![GridTrack::fraction(1.0); 2],
        Some(columns) => match columns.as_f64() {
            Some(count) => vec![GridTrack::fraction(1.0); (count as u32 as usize).max(1)],
            None if Array::is_array(&columns) => js_grid_tracks(columns.unchecked_ref())?,
            None => {
                return Err(invalid_arg(
                    "columns must be a number or an array of tracks",
                ));
            }
        },
    };
    let rows = rows
        .as_ref()
        .map(js_grid_tracks)
        .transpose()?
        .unwrap_or_default();
    Ok(JsWidget::from_binding(BindingWidget::grid_with_tracks(
        columns,
        rows,
        extract_binding_widgets(&children)?,
        name,
        column_gap.map(|value| value as f32).unwrap_or(gap),
        row_gap.map(|value| value as f32).unwrap_or(gap),
    )))
}

#[wasm_bindgen(js_name = GridCell)]
