#[wasm_bindgen(js_name = VirtualTable)]
pub fn js_virtual_table(
    name: String,
    columns: Array,
    model: &JsTableModel,
    selected: Option<ClassArg<JsState>>,
    row_height: Option<f64>,
    on_change: Option<Function>,
    on_row_activate: Option<Function>,
    on_header_activate: Option<Function>,
    on_column_resize: Option<Function>,
    on_near_end: Option<Function>,
    enabled: Option<JsBindingBoolArg>,
) -> Result<JsWidget> {
    let selected = selected.map(|value| value.value()).transpose()?;
    let selected = selected.as_ref();
    let column_values = columns
        .iter()
        .map(|column| Ok(class_ref::<JsVirtualTableColumn>(&column)?.inner.clone()))
        .collect::<Result<Vec<_>>>()?;
    let options = sui_bindings_core::BindingVirtualTableOptions {
        selected: selected.map(|state| state.inner.clone()),
        row_height: row_height.map(|value| value as f32),
        on_change: js_id_action(on_change),
        on_row_activate: js_id_action(on_row_activate),
        on_header_activate: js_id_action(on_header_activate),
        on_column_resize: js_id_number_action(on_column_resize),
        on_near_end: js_action(on_near_end),
    };
    JsWidget::from_binding(BindingWidget::virtual_table(
        name,
        column_values,
        model.inner.clone(),
        options,
    ))
    .with_enabled(enabled)
}

