#[wasm_bindgen(js_name = SideSheet)]
pub fn js_side_sheet(
    title: String,
    body: &JsWidget,
    description: Option<String>,
    open: Option<JsBindingBoolArg>,
    modal: Option<bool>,
    dismiss_on_scrim: Option<bool>,
    placement: Option<String>,
    width: Option<f64>,
    header_action: Option<ClassArg<JsWidget>>,
    actions: Option<Array>,
    on_dismiss: Option<Function>,
) -> Result<JsWidget> {
    let header_action = header_action.map(|value| value.borrow()).transpose()?;
    let header_action = header_action.as_ref();
    let placement = match placement.as_deref().unwrap_or("right") {
        "left" => sui_crate::SideSheetPlacement::Left,
        "right" => sui_crate::SideSheetPlacement::Right,
        _ => {
            return Err(invalid_arg(
                "side sheet placement must be 'left' or 'right'",
            ));
        }
    };
    Ok(JsWidget::from_binding(BindingWidget::side_sheet(
        title,
        body.binding_widget()?,
        description,
        open.map(binding_bool_from_js)
            .transpose()?
            .unwrap_or(BindingBool::Static(true)),
        modal.unwrap_or(true),
        dismiss_on_scrim.unwrap_or(true),
        placement,
        width.map(|value| value as f32),
        header_action
            .map(|widget| widget.binding_widget())
            .transpose()?,
        actions
            .as_ref()
            .map(extract_binding_widgets)
            .transpose()?
            .unwrap_or_default(),
        js_action(on_dismiss),
    )))
}

